schema_sql:
CREATE TABLE customers (
  customer_id   INTEGER,
  name          VARCHAR,
  city          VARCHAR,
  registered_on DATE
);
CREATE TABLE products (
  product_id INTEGER,
  name       VARCHAR,
  category   VARCHAR,
  cost       INTEGER      -- 原価
);
CREATE TABLE orders (
  order_id    INTEGER,
  customer_id INTEGER,
  order_date  DATE,
  status      VARCHAR     -- '完了' または 'キャンセル'
);
CREATE TABLE order_items (
  order_id   INTEGER,
  item_no    INTEGER,
  product_id INTEGER,
  qty        INTEGER,
  unit_price INTEGER      -- 受注時点の販売単価
);

